"""Build a local gallery from the Unreal capture outputs; no raster processing."""
from pathlib import Path
import json
ROOT=Path(__file__).resolve().parents[1]
config=json.loads((ROOT/'Art/ArenaVariations/Variants.json').read_text())
variants=config['variants']
html=r'''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1">
<title>Heaven's Divide ? ten arena surfaces</title>
<style>
:root{color-scheme:dark;font:16px/1.5 system-ui,sans-serif;background:#13171c;color:#e8e8e4}*{box-sizing:border-box}body{margin:0}main{max-width:1500px;margin:auto;padding:40px 28px 70px}h1{font-size:clamp(28px,4vw,48px);line-height:1.1;margin:8px 0 18px;font-weight:650;letter-spacing:-.025em}p{color:#adb7bd;max-width:900px}.eyebrow{color:#acbd94;font-size:13px;letter-spacing:.14em;text-transform:uppercase}nav{display:flex;flex-wrap:wrap;gap:10px;margin:28px 0}button,a{color:inherit}button{background:#222b33;border:1px solid #42505a;border-radius:7px;padding:9px 15px;cursor:pointer;font:inherit}button.active{background:#c5d3b6;color:#192018;border-color:#c5d3b6}a{color:#c5d3b6;text-underline-offset:4px}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(340px,1fr));gap:22px}article{background:#1d232b;border:1px solid #35414a;border-radius:12px;overflow:hidden}article img{display:block;width:100%;aspect-ratio:16/9;object-fit:contain;background:#0c1014;cursor:zoom-in}.square article img{aspect-ratio:1}article .body{padding:16px 18px 20px}h2{font-size:20px;margin:0 0 7px}.id{color:#a8ba96;margin-right:8px;font-variant-numeric:tabular-nums}.hint{font-size:13px;color:#a1abb4;margin:0 0 14px}.links{display:flex;gap:18px;font-size:14px}details{margin-top:16px}summary{cursor:pointer;color:#bbc6cf;font-size:14px}code{display:block;overflow-wrap:anywhere;font:12px/1.5 ui-monospace,monospace;color:#cbd7e0;margin-top:10px}footer{border-top:1px solid #35414a;margin-top:38px;padding-top:20px}dialog{border:1px solid #536169;border-radius:10px;max-width:96vw;padding:8px;background:#10151b;color:#eee}dialog::backdrop{background:#000d}dialog img{max-width:92vw;max-height:83vh;display:block}dialog .bar{display:flex;justify-content:space-between;align-items:center;gap:20px;padding:10px}@media(max-width:500px){main{padding:28px 16px}.grid{grid-template-columns:1fr}}
</style><main><div class="eyebrow">Heaven's Divide / Level 1</div><h1>Ten arena surfaces</h1>
<p>Smaller painted forms, muted surface detail, and coordinated stone borders. These previews use the same saved arena lighting. Gameplay views include a temporary Samurai for scale.</p>
<p>Initial selection: <strong>01 Verdant ochre</strong>. Click any image to inspect it at full size.</p>
<nav aria-label="Preview mode"><button data-mode="Gameplay" class="active">Gameplay camera</button><button data-mode="Overview">Whole arena</button><button data-mode="Artwork">Source artwork</button></nav>
<div class="grid" id="grid"></div>
<footer><p>Primary tile: 14 m. Source artwork: 1254 ? 1254 native pixels per variant. Native source density is 7.86? the previous 110 m mapping. Normal texture streaming and mipmaps remain active; runtime texture conversion does not add new source detail.</p><p><a href="../../Art/ArenaVariations/README.md">Preset selection, source assets and prompts</a> ? <a href="../../Art/ArenaVariations/Research.md">Riot research and applied choices</a> ? <a href="ValidationSummary.json">Validation evidence</a> ? <a href="FinalReload/Default_StoneRim.png">Stone border view</a></p></footer>
</main><dialog id="lightbox"><div class="bar"><span id="caption"></span><button id="close">Close</button></div><img id="large" alt=""></dialog>
<script>
const variants=VARIANTS;
let mode='Gameplay';
const grid=document.querySelector('#grid'),dialog=document.querySelector('#lightbox');
const path=v=>mode==='Artwork'?'../../Art/ArenaVariations/'+v.source:'FinalReload/'+v.id+'_'+mode+'.png';
function render(){grid.classList.toggle('square',mode!=='Gameplay');grid.replaceChildren();for(const v of variants){let card=document.createElement('article');let img=document.createElement('img');img.src=path(v);img.alt=v.title+' ? '+mode;img.loading='lazy';img.onclick=()=>{document.querySelector('#large').src=img.src;document.querySelector('#large').alt=img.alt;document.querySelector('#caption').textContent=img.alt;dialog.showModal()};card.append(img);let body=document.createElement('div');body.className='body';let heading=document.createElement('h2');heading.textContent=v.id.slice(0,2)+'  '+v.title;body.append(heading);let hint=document.createElement('p');hint.className='hint';hint.textContent='MI_'+v.id+' ? matching rim preset';body.append(hint);let links=document.createElement('div');links.className='links';for(const [label,href] of [['Full image',path(v)],['Prompt','../../Art/ArenaVariations/'+v.prompt]]){let a=document.createElement('a');a.textContent=label;a.href=href;links.append(a)}body.append(links);let details=document.createElement('details');let summary=document.createElement('summary');summary.textContent='Select in Unreal';details.append(summary);let code=document.createElement('code');code.textContent='py import runpy, unreal; runpy.run_path(unreal.Paths.project_dir()+"Tools/select_arena_variation.py", init_globals={"VARIANT_ID":"'+v.id+'"})';details.append(code);body.append(details);card.append(body);grid.append(card)}}
for(const b of document.querySelectorAll('nav button'))b.onclick=()=>{mode=b.dataset.mode;document.querySelectorAll('nav button').forEach(x=>x.classList.toggle('active',x===b));render()};document.querySelector('#close').onclick=()=>dialog.close();dialog.onclick=e=>{if(e.target===dialog)dialog.close()};render();
</script></html>'''
html=html.replace('VARIANTS',json.dumps(variants))
out=ROOT/'Saved/ArenaVariations/Gallery.html';out.write_text(html,encoding='utf-8');print(out)
